    void testFindExactMatchingStaticMethod() {
        Object[] params = { "test" };
        Method method = MethodLookupUtils.lookupStaticMethod(String.class, "valueOf", params);
        assertNotNull(method);
        assertEquals("valueOf", method.getName());
        assertTrue(java.lang.reflect.Modifier.isStatic(method.getModifiers()));
    }

