    @DisplayName("Should return null when no matching method is found")
    void testReturnNullWhenNoMethodFound() {
        Object[] params = { 1, "test" };
        Method method = MethodLookupUtils.lookupStaticMethod(String.class, "nonExistentMethod", params);
        assertNull(method);
    }

    @Test
    @DisplayName("Should find static method with type conversion")
    void testFindStaticMethodWithTypeConversion() {
        Object[] params = { 123 }; // Integer, but method expects int
